import brand from "@/data/brand.json";

// The Drox.dev wordmark as the header's partner mark, like a shirt sponsor in a
// big club's navbar. Generated by scripts/brand.ts.
export function DroxdevMark({ className = "" }: { className?: string }) {
  const { droxdev } = brand;
  return (
    <a
      href="https://droxdev.com"
      target="_blank"
      rel="sponsored noopener noreferrer"
      className={`inline-flex shrink-0 items-center opacity-90 transition-opacity hover:opacity-100 ${className}`}
    >
      {/* eslint-disable-next-line @next/next/no-img-element -- pre-built WebP sizes, see scripts/brand.ts */}
      <img
        src={droxdev.src}
        srcSet={droxdev.srcSet}
        sizes="(min-width: 640px) 100px, 88px"
        width={droxdev.width}
        height={droxdev.height}
        alt="Drox.dev"
        decoding="async"
        className="h-4 w-auto sm:h-4.5"
      />
      <span className="sr-only">, technology partner (opens in a new tab)</span>
    </a>
  );
}
